<body>
<div class="phone-container">
    <div class="phone-notch"><div class="notch-sensor"></div><div class="notch-camera"></div><div class="notch-speaker"></div><div class="notch-sensor"></div></div>
    <div class="main-screen-container">
        <div class="phone-header">
            <svg class="back-arrow-btn" viewBox="0 0 24 24"><path fill="currentColor" d="M15.41 16.59L10.83 12l4.58-4.59L14 6l-6 6 6 6 1.41-1.41z"/></svg>
            <h2>帖子详情</h2>
            <div class="header-icons"><svg class="header-icon" viewBox="0 0 24 24"><path fill="currentColor" d="M12,8c1.1,0,2-0.9,2-2s-0.9-2-2-2s-2,0.9-2,2S10.9,8,12,8z M12,10c-1.1,0-2,0.9-2,2s0.9,2,2,2s2-0.9,2-2S13.1,10,12,10z M12,16c-1.1,0-2,0.9-2,2s0.9,2,2,2s2-0.9,2-2S13.1,16,12,16z" /></svg></div>
        </div>
        <div class="phone-content-area">
            <div id="forum-detail-wrapper"></div>
            <textarea id="forum-detail-data-source-blmx" style="display:none;">$2</textarea>
        </div>
    </div>
</div>

<script>
    (() => {
        const wrapper = document.getElementById('forum-detail-wrapper');
        if (!wrapper || wrapper.dataset.rendered) return;
        wrapper.dataset.rendered = 'true';
        const dataSource = document.getElementById('forum-detail-data-source-blmx');
        if (!dataSource || dataSource.dataset.processed) return;
        dataSource.dataset.processed = 'true';

        try {
            let rawText = dataSource.value;
            if (!rawText.trim().endsWith('[帖子详情结束]')) rawText += '\n[帖子详情结束]';

            const mainRaw = (rawText.match(/\[主楼\]([\s\S]*?)\[\/主楼\]/) || [])[1] || '';
            let commentsRaw = (rawText.match(/\[评论区\]([\s\S]*?)\[\/评论区\]/) || [])[1] || '';
            if (commentsRaw && !commentsRaw.match(/\[\/最新评论列表\]/)) commentsRaw += '\n[/最新评论列表]';

            const processContentToImageCard = (content) => {
                return content.replace(/<tp>([\s\S]*?)<\/tp>/g, (match, desc) => {
                    const cleanDesc = desc.trim().replace(/\n/g, '<br>');
                    const randomBg = `https://source.unsplash.com/random/160x160?sig=${Math.random()}`;
                    return `<div class="image-card" style="background-image: url('${randomBg}');"><div class="image-card-desc"><p>${cleanDesc}</p></div></div>`;
                });
            };

            let post = { title: '', author: '未知', time: '', content: [], interactions: '' };
            if (mainRaw) {
                const mainLines = mainRaw.trim().split(/\r?\n/).filter(line => line.trim() !== '');
                let currentField = '';
                for (const line of mainLines) {
                    const trimmedLine = line.trim();
                    if (trimmedLine.startsWith('标题:')) { post.title = trimmedLine.substring(3).trim(); currentField = ''; continue; }
                    if (trimmedLine.startsWith('发帖人:')) { post.author = trimmedLine.substring(4).trim(); currentField = ''; continue; }
                    if (trimmedLine.startsWith('发帖时间:')) { post.time = trimmedLine.substring(5).trim(); currentField = ''; continue; }
                    if (trimmedLine.startsWith('互动数:')) { post.interactions = trimmedLine.substring(4).trim(); currentField = ''; continue; }
                    if (trimmedLine.startsWith('内容:')) { post.content.push(trimmedLine.substring(3).trim()); currentField = 'content'; continue; }
                    if (currentField === 'content') { post.content.push(trimmedLine); }
                }
            }
            const finalContent = processContentToImageCard(post.content.join('\n'));
            const interactionsMatch = post.interactions.match(/点赞\s*([\d+]+)[,，\s]*评论\s*([\d+]+)/);
            let interactionsHtml = post.interactions;
            if (interactionsMatch) {
                interactionsHtml = `<span><i class="fa-solid fa-thumbs-up"></i>${interactionsMatch[1]}</span><span><i class="fa-solid fa-comment"></i>${interactionsMatch[2]}</span>`;
            }

            const parseComments = (rawCommentBlock) => {
                if (!rawCommentBlock) return '';
                const commentMatches = [...rawCommentBlock.matchAll(/\[评论\]([\s\S]*?)\[\/评论\]/g)];
                let html = '';
                for (const match of commentMatches) {
                    const commentRaw = match[1].trim();
                    let comment = { floor: '', author: '匿名', time: '', content: [], likes: '0' };
                    const commentLines = commentRaw.split(/\r?\n/).filter(line => line.trim() !== '');
                    let currentField = '';
                    for(const line of commentLines) {
                        const trimmedLine = line.trim();
                        if(trimmedLine.startsWith('楼层:')) { comment.floor = trimmedLine.substring(3).trim(); currentField = ''; continue; }
                        if(trimmedLine.startsWith('评论者:')) { comment.author = trimmedLine.substring(4).trim(); currentField = ''; continue; }
                        if(trimmedLine.startsWith('时间:')) { comment.time = trimmedLine.substring(3).trim(); currentField = ''; continue; }
                        if(trimmedLine.startsWith('点赞:')) { comment.likes = trimmedLine.substring(3).trim(); currentField = ''; continue; }
                        if(trimmedLine.startsWith('内容:')) { comment.content.push(trimmedLine.substring(3).trim()); currentField = 'content'; continue; }
                        if(currentField === 'content') { comment.content.push(trimmedLine); }
                    }

                    let processedContent = comment.content.join('\n');
                    const formalReplyRegex = /(?:回复\s*[:：]?\s*)?\[评论者\]([^\[\]]+)\[\/评论者\]\s*[:：]?\s*/gi;
                    processedContent = processedContent.replace(formalReplyRegex, (match, username) => `<span class="comment-reply-blmx">@${username.trim()}</span> `);
                    const bracketedMentionRegex = /\[(@[^\]]+)\]/g;
                    processedContent = processedContent.replace(bracketedMentionRegex, (match, fullMention) => {
    if (fullMention === '@我') {
        return fullMention;
    }
    return `<span class="comment-reply-blmx">${fullMention}</span>`;
});

                    const mentionRegex = /(?<!>)@([^,.:;!?，。：；！？\s<>]+)/g;
                    processedContent = processedContent.replace(mentionRegex, (fullMatch, username) => {
    if (username === '我') {
        return fullMatch;
    }
    if (fullMatch.includes('<span')) {
        return fullMatch;
    }
    return `<span class="comment-reply-blmx">${fullMatch}</span>`;
});

                    const finalCommentHtml = processContentToImageCard(processedContent);

                    const likeCount = parseInt(comment.likes, 10) || 0;
                    const likeHtml = likeCount > 0 
                        ? `<span class="comment-like-action-blmx"><i class="fa-solid fa-thumbs-up"></i><span>${likeCount}</span></span>`
                        : `<span class="comment-like-action-blmx"><i class="fa-solid fa-thumbs-up"></i></span>`;

                    html += `
                        <div class="comment-card-blmx">
                            <div class="comment-avatar-blmx">${comment.author.charAt(0) || '?'}</div>
                            <div class="comment-main-blmx">
                                <div class="comment-meta-top-blmx">
                                    <div class="comment-author-time-wrapper-blmx"><span class="comment-author-blmx">${comment.author}</span><span class="comment-time-blmx">${comment.time}</span></div>
                                    <span class="comment-floor-blmx">${comment.floor}楼</span>
                                </div>
                                <div class="comment-content-blmx">${finalCommentHtml}</div>
                                <div class="comment-actions-blmx">${likeHtml}<i class="fa-solid fa-reply reply-icon-blmx" title="回复"></i></div>
                            </div>
                        </div>`;
                }
                return html;
            };

            const hotCommentsRaw = (commentsRaw.match(/\[热门评论列表\]([\s\S]*?)\[\/热门评论列表\]/) || [])[1] || '';
            const latestCommentsRaw = (commentsRaw.match(/\[最新评论列表\]([\s\S]*?)\[\/最新评论列表\]/) || [])[1] || '';
            const hotCommentsHtml = parseComments(hotCommentsRaw);
            const latestCommentsHtml = parseComments(latestCommentsRaw);

            const renderedHtml = `
                <div class="forum-container-blmx">
                    <div class="post-scroll-wrapper-blmx">
                        <div class="post-content-area-blmx">
                            <div class="main-post-body-blmx">
                                <div class="post-header-blmx">
                                    <h1 class="detail-title-blmx">${post.title}</h1>
                                    <div class="post-author-row-blmx">
                                        <div class="main-post-avatar-blmx">${post.author.charAt(0) || '?'}</div>
                                        <div class="detail-author-meta-blmx">由 <strong>${post.author}</strong> 发布于 ${post.time}</div>
                                    </div>
                                    <div class="detail-content-blmx">${finalContent}</div>
                                    <div class="detail-interactions-blmx">${interactionsHtml}</div>
                                </div>
                            </div>
                            <div class="comment-section-wrapper-blmx">
                                <div class="comment-section-blmx">
                                    <div class="comment-tab-header-blmx">
                                        <div class="comment-tab-blmx active-tab-blmx" data-tab="hot">热门评论</div>
                                        <div class="comment-tab-blmx" data-tab="latest">最新评论</div>
                                    </div>
                                    <div id="panel-hot" class="comment-panel-blmx active-panel-blmx">${hotCommentsHtml || '<div style="padding: 20px; text-align: center; color: #999;">暂无热门评论</div>'}</div>
                                    <div id="panel-latest" class="comment-panel-blmx">${latestCommentsHtml || '<div style="padding: 20px; text-align: center; color: #999;">暂无最新评论</div>'}</div>
                                </div>
                            </div>
                            <div class="main-reply-box-wrapper-blmx">
                                <div class="main-reply-box-blmx">
                                    <textarea class="main-reply-textarea-blmx" placeholder="发表你的回复..."></textarea>
                                    <button class="main-reply-button-blmx">发表回复</button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
                <div class="modal-overlay-blmx">
                    <div class="modal-content-blmx">
                        <div class="modal-header-blmx">回复</div>
                        <div class="modal-body-blmx"><textarea></textarea></div>
                        <div class="modal-footer-blmx"><button class="modal-btn-cancel-blmx">取消</button><button class="modal-btn-confirm-blmx">确认</button></div>
                    </div>
                </div>`;

            wrapper.innerHTML = renderedHtml;
            dataSource.remove();

            // --- 核心交互逻辑 --- //
            let replyTarget = { author: null };
            const phoneScreen = document.querySelector('.main-screen-container');
            const modal = phoneScreen.querySelector('.modal-overlay-blmx');

            wrapper.addEventListener('click', (e) => {
                const tab = e.target.closest('.comment-tab-blmx');
                if (tab && !tab.classList.contains('active-tab-blmx')) {
                    const tabContainer = tab.parentElement;
                    const targetTab = tab.dataset.tab;
                    tabContainer.querySelector('.active-tab-blmx').classList.remove('active-tab-blmx');
                    tab.classList.add('active-tab-blmx');
                    wrapper.querySelector('.comment-panel-blmx.active-panel-blmx').classList.remove('active-panel-blmx');
                    wrapper.querySelector(`#panel-${targetTab}`).classList.add('active-panel-blmx');
                }

                const replyIcon = e.target.closest('.reply-icon-blmx');
                if (replyIcon) {
                    const author = replyIcon.closest('.comment-card-blmx').querySelector('.comment-author-blmx').textContent;
                    replyTarget.author = author; 
                    modal.querySelector('.modal-header-blmx').textContent = `回复 @${author}`;
                    modal.querySelector('textarea').value = '';
                    modal.style.display = 'flex';
                    modal.querySelector('textarea').focus();
                }

                const imageCard = e.target.closest('.image-card');
                if(imageCard && !e.target.closest('.image-card-desc')) { imageCard.classList.toggle('show-desc'); }

                const mainReplyBtn = e.target.closest('.main-reply-button-blmx');
                if(mainReplyBtn) {
                    const textarea = wrapper.querySelector('.main-reply-textarea-blmx');
                    const content = textarea.value.trim();
                    if (content && typeof triggerSlash === 'function') {
                        const commandText = `论坛操作|操作:回主楼|内容:${content}|`;
                        const safeCommand = commandText.replace(/\|/g, '\\|');
                        triggerSlash(`/send ${safeCommand}|/trigger`);
                        textarea.value = '';
                    }
                }
            });

            if(modal) {
                phoneScreen.appendChild(modal);

                modal.addEventListener('click', (e) => {
                    if (e.target.classList.contains('modal-btn-cancel-blmx') || e.target === modal) {
                        modal.style.display = 'none';
                        replyTarget.author = null; 
                    }
                    if (e.target.classList.contains('modal-btn-confirm-blmx')) {
                        if (replyTarget.author) {
                            const modalText = modal.querySelector('textarea');
                            const content = modalText.value.trim();
                             if (content && typeof triggerSlash === 'function') {
                                const commandText = `论坛操作|操作:回评论|目标昵称:${replyTarget.author}|内容:${content}|`;
                                const safeCommand = commandText.replace(/\|/g, '\\|');
                                triggerSlash(`/send ${safeCommand}|/trigger`);
                            }
                        }
                        modal.style.display = 'none';
                        replyTarget.author = null; 
                    }
                });
            }
        } catch (error) {
            wrapper.innerHTML = `<div style='padding:20px; text-align:center; color: red;'><h3>渲染失败!</h3><p>${error.message}</p></div>`;
        }
    })();
</script>
